"""Time-ordered unique IDs (UUIDv7, RFC 9562).

Why UUIDv7 for primary keys (docs/database-design.md, decision D-6):

* Generated by the application, so an ID exists *before* the INSERT. Later it
  doubles as an idempotency key and a Qdrant point ID.
* Not guessable or sequential like 1, 2, 3, so IDs in URLs don't leak volumes.
* The first 48 bits are a millisecond timestamp, so new IDs sort after old
  ones. B-tree index inserts then land at the right edge of the index instead
  of random pages, which keeps writes fast as tables grow. Random UUIDv4 keys
  scatter writes across the whole index.

Layout (128 bits): 48-bit unix_ts_ms | 4-bit version (7) | 12 random bits |
2-bit variant (0b10) | 62 random bits.
"""

import secrets
import time
import uuid


def _uuid7_fallback() -> uuid.UUID:
    timestamp_ms = time.time_ns() // 1_000_000
    value = (
        (timestamp_ms & 0xFFFF_FFFF_FFFF) << 80
        | 0x7 << 76  # version 7
        | secrets.randbits(12) << 64
        | 0b10 << 62  # RFC 9562 variant
        | secrets.randbits(62)
    )
    return uuid.UUID(int=value)


def new_id() -> uuid.UUID:
    """Return a new UUIDv7. Uses the standard library on Python 3.14+."""
    stdlib_uuid7 = getattr(uuid, "uuid7", None)
    if stdlib_uuid7 is not None:  # pragma: no cover - depends on the Python version
        result: uuid.UUID = stdlib_uuid7()
        return result
    return _uuid7_fallback()
